"""Local native-UI stand-in. Uses only explicitly supplied QA state/journal paths.

Never imports a model SDK, contacts a provider, or reads credentials. Only use the
wrapper generated by scripts/native-codex-qa.mjs, scoped to its isolated app.
"""
import json
import os
from pathlib import Path
import sqlite3
import sys
import uuid

root = Path(os.environ["BLACKCRAB_QA_STATE"])
root.mkdir(parents=True, exist_ok=True)
wire = root / "wire.jsonl"
journal = Path(os.environ["BLACKCRAB_QA_JOURNAL"])
initialized = False
thread_id = None
active = None
approval = None

def send(value):
    print(json.dumps(value, separators=(",", ":")), flush=True)

def log(**values):
    with wire.open("a") as output:
        output.write(json.dumps({"pid": os.getpid(), **values}) + "\n")

def read_thread(identifier):
    # UUID-only filenames prevent a request from reading arbitrary files.
    identifier = str(uuid.UUID(identifier))
    return json.loads((root / (identifier + ".json")).read_text())

def save_thread(thread):
    target = root / (str(uuid.UUID(thread["id"])) + ".json")
    temporary = target.with_suffix(".tmp")
    temporary.write_text(json.dumps(thread))
    temporary.replace(target)

def event(method, **values):
    send({"method": method, "params": {"threadId": thread_id, "turnId": active, **values}})

def finish(status="completed", text="Native QA fixture reply"):
    global active, approval
    item = {"id": "assistant-" + active, "type": "agentMessage", "text": text}
    event("item/completed", item=item)
    event("thread/tokenUsage/updated", tokenUsage={"total": {"inputTokens": 1, "outputTokens": 1}, "last": {"inputTokens": 1, "outputTokens": 1}, "modelContextWindow": 1000})
    thread = read_thread(thread_id)
    thread["turns"].append({"id": active, "status": status, "items": [item], "itemsView": "full", "error": None})
    save_thread(thread)
    event("turn/completed", turn={"id": active, "status": status, "items": [item], "error": None})
    log(phase="turn/completed", threadId=thread_id, turnId=active, status=status)
    active = None
    approval = None

for line in sys.stdin:
    request = json.loads(line)
    method, params = request.get("method"), request.get("params", {})
    if method == "initialize":
        send({"id": request["id"], "result": {"userAgent": "Blackcrab native QA fixture"}})
        continue
    if method == "initialized":
        initialized = True
        continue
    assert initialized
    log(phase=method or "approval-answer")
    try:
        if method == "model/list":
            model = {"id": "native-qa", "model": "native-qa", "displayName": "Native QA fixture", "description": "Local stand-in; no provider requests", "hidden": False, "isDefault": True, "defaultReasoningEffort": "none", "supportedReasoningEfforts": [{"reasoningEffort": "none", "description": "No model execution"}], "inputModalities": ["text"]}
            result = {"data": [model] if not params.get("cursor") else [], "nextCursor": None}
        elif method == "account/read":
            assert params.get("refreshToken") is False
            result = {"account": None, "requiresOpenaiAuth": False}
        elif method == "thread/list":
            threads = [json.loads(file.read_text()) for file in sorted(root.glob("*.json"))]
            for thread in threads:
                thread["turns"] = []
            result = {"data": threads[:params.get("limit", 50)] if not params.get("archived") else [], "nextCursor": None}
        elif method in ("thread/start", "thread/resume"):
            assert params["approvalPolicy"] == "on-request"
            assert params["sandbox"] in ("read-only", "workspace-write")
            assert active is None
            if method == "thread/start":
                thread = {"id": str(uuid.uuid4()), "name": "Native QA thread", "preview": "Local fixture", "cwd": os.getcwd(), "model": params.get("model") or "native-qa", "modelProvider": "native-qa", "createdAt": 1, "updatedAt": 1, "historyMode": "legacy", "status": {"type": "notLoaded"}, "turns": []}
                save_thread(thread)
            else:
                thread = read_thread(params["threadId"])
                assert thread["cwd"] == os.getcwd()
            thread_id = thread["id"]
            result = {"thread": thread, "cwd": os.getcwd(), "model": thread["model"]}
        elif method == "thread/read":
            thread = read_thread(params["threadId"])
            if not params.get("includeTurns"):
                thread["turns"] = []
            result = {"thread": thread}
        elif method == "thread/turns/list":
            turns = list(reversed(read_thread(params["threadId"])["turns"]))[:params.get("limit", 50)]
            for turn in turns:
                turn["itemsView"] = params.get("itemsView", "notLoaded")
                if turn["itemsView"] == "notLoaded":
                    turn["items"] = []
            result = {"data": turns, "nextCursor": None}
        elif method == "thread/items/list":
            turns = read_thread(params["threadId"])["turns"]
            result = {"data": [{"turnId": turn["id"], "item": item} for turn in turns if not params.get("turnId") or params["turnId"] == turn["id"] for item in turn["items"]][:params.get("limit", 50)], "nextCursor": None}
        elif method == "turn/start":
            assert active is None
            assert params["threadId"] == thread_id
            command = params["clientUserMessageId"]
            with sqlite3.connect(journal) as db:
                receipt = db.execute("SELECT status FROM turns WHERE command_id=?", [command]).fetchone()
            assert receipt == ("dispatching",), "input preceded its durable receipt"
            active = str(uuid.uuid4())
            body = params["input"][0]["text"]
            log(phase="input-recorded", commandId=command, threadId=thread_id, turnId=active, statusBeforeInput=receipt[0], body=body)
            send({"id": request["id"], "result": {"turn": {"id": active, "status": "inProgress", "items": []}}})
            event("turn/started", turn={"id": active, "status": "inProgress", "items": []})
            event("item/agentMessage/delta", itemId="assistant-" + active, delta="Native QA streaming text")
            if body == "approval":
                approval = "approval-" + active
                send({"id": approval, "method": "item/commandExecution/requestApproval", "params": {"threadId": thread_id, "turnId": active, "itemId": "tool-" + active, "command": "fixture only; nothing is executed"}})
            elif body != "hold":
                finish()
            continue
        elif method == "turn/interrupt":
            assert params["turnId"] == active
            finish("interrupted")
            result = {}
        elif method is None:
            assert request["id"] == approval
            decision = request["result"]["decision"]
            assert decision in ("accept", "decline", "cancel")
            log(phase="approval-decision", decision=decision, turnId=active)
            finish("interrupted" if decision == "cancel" else "completed")
            continue
        else:
            send({"id": request["id"], "error": {"code": -32601, "message": "Native QA fixture method unavailable"}})
            continue
        send({"id": request["id"], "result": result})
    except Exception as error:
        log(phase="fixture-error", error=str(error))
        send({"id": request.get("id"), "error": {"code": -32000, "message": "Native QA fixture rejected the scenario"}})
